const e=["Dieu","Destruction","Feu","Religion","Force","Magie"],t="Détruire est facile. Savoir quoi détruire est une autre affaire.",s="Dieu de la Destruction",r=["Rhabus représente la Destruction.","Il n'est pas le dieu du Mal.","La destruction peut être monstrueuse, mais elle peut aussi être nécessaire.","Une forêt brûle et renaît.","Une vieille cité s'effondre.","Un empire disparaît.","Une arme est détruite avant de pouvoir tuer.","Rhabus incarne ce moment où quelque chose cesse d'exister sous sa forme actuelle."],n=[{label:"Domaines",value:"Destruction"},{label:"Symboles",value:"Une flamme, un volcan, une pierre brisée, un bâtiment en ruines, un marteau, un cercle consumé par le feu"}],a=[{title:"La destruction",title_border:"#e8553d",type:"text",content:["Pour les fidèles de Rhabus, toute chose possède une limite.","Les constructions, les royaumes, les traditions et même les civilisations peuvent devenir incapables de changer.","La destruction brise alors ce qui ne peut plus évoluer.","Mais Rhabus n'affirme pas que toute destruction est nécessaire.","Détruire peut libérer.","Détruire peut également condamner.","La différence appartient aux mortels qui choisissent de frapper."]},{title:"Le feu",title_border:"#c2660a",type:"text",content:["Rhabus est particulièrement associé au feu.","Le feu représente parfaitement sa Force.","Il détruit rapidement, transforme ce qu'il touche et laisse derrière lui des traces impossibles à ignorer.","Mais le feu peut également réchauffer, éclairer et permettre de reconstruire.","Cette dualité est au cœur de son culte."]},{title:"Le culte de Rhabus",title_border:"#6f9fd8",type:"text",content:["Les fidèles de Rhabus sont très différents selon les régions.","Certains sont des pyromanciens fascinés par les flammes.","D'autres sont des artisans travaillant avec le feu : forgerons, verriers ou métallurgistes.","Certains encore sont des guerriers qui considèrent la destruction comme une forme de libération.","Les cultes les plus extrêmes peuvent toutefois devenir dangereux.","Car il existe une frontière difficile à déterminer entre détruire ce qui doit disparaître et détruire simplement parce que l'on en est capable."]},{title:"Rhabus et Quaara",title_border:"#e8553d",type:"text",content:["Rhabus entretient une relation particulière avec Quaara.","La Nature détruit autant qu'elle crée.","Les arbres tombent, les montagnes s'érodent, les incendies ravagent les forêts et les espèces disparaissent.","La destruction n'est donc pas étrangère à la Nature.","Pour certains fidèles de Quaara, Rhabus représente cependant la version incontrôlée de ce phénomène lorsque les mortels interviennent."]},{title:"Rhabus et Metona",title_border:"#c2660a",type:"text",content:["La relation entre Rhabus et Metona représente une autre opposition.","Metona représente la Vie.","Rhabus représente ce qui met fin aux formes existantes.","Ils ne sont pourtant pas des ennemis absolus.","La Vie transforme constamment ce qui existe.","La destruction transforme également ce qui existe.","Le conflit entre eux n'est donc pas simplement celui de la création contre la destruction.","Il concerne plutôt ce qui mérite de continuer à exister sous sa forme actuelle."]},{title:"Symboles",title_border:"#6f9fd8",type:"text",content:"Rhabus est généralement représenté par :"},{title:"",type:"list",content:["Une flamme","Un volcan","Une pierre brisée","Un bâtiment en ruines","Un marteau","Un cercle consumé par le feu"]},{title:"",type:"text",content:"Le symbole le plus courant est une flamme traversant un cercle, représentant quelque chose qui disparaît pour laisser place à autre chose."},{title:"Aujourd'hui",title_border:"#e8553d",type:"text",content:["Le culte de Rhabus reste marginal dans de nombreuses régions.","Il est cependant impossible d'ignorer son influence.","Les guerres, les incendies, les catastrophes naturelles et les grandes chutes de royaumes sont souvent interprétés à travers son image.","Les prêtres de Rhabus rappellent toutefois une vérité moins spectaculaire :"]}],i=["Les Dieux","Les Forces","Quaara","Metona","La Nature","La Destruction"],u={tags:e,citation:t,surname:s,presentation:r,infos:n,sections:a,related:i};export{t as citation,u as default,n as infos,r as presentation,i as related,a as sections,s as surname,e as tags};
